def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_597: no hunk on ' + rel)
    for old, new, n in HUNKS[rel]:
        if new in txt:
            raise SystemExit('ashira_597: the live %s already holds the new text' % rel)
        k = txt.count(old)
        if k != n:
            raise SystemExit('ashira_597: anchor x%d (want %d) in the live %s' % (k, n, rel))
        txt = txt.replace(old, new)
    return txt
